    @Test
    public void testGetTypeAlternatives_UnionType() {
        // Arrange
        when(unionType.isUnionType()).thenReturn(true);
        when(unionType.getAlternates()).thenReturn(Lists.newArrayList(objectType, implType1));

        // Act
        Iterable<JSType> result = typeSystem.getTypeAlternatives(unionType);

        // Assert
        assertThat(result).containsExactly(objectType, implType1);
        verify(unionType).isUnionType();
        verify(unionType).getAlternates();
    }

